package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class SectorPerimeterRelationsTest {
 @Test public void publicDimensionsIndependentlyDeterminePerimeter(){Generator g=new Generator(new Random(1860));Set<String> variants=new HashSet<>();for(int i=0;i<600;i++){Question q=g.next("sectorPerimeter",List.of(),i%2==0);Matcher m=Pattern.compile("반지름: (.*?)cm · 중심각: (.*?)°\\nπ = (.*?) 사용").matcher(q.prompt);assertTrue(m.find());Rational radius=Expression.number(m.group(1)),angle=Expression.number(m.group(2)),pi=Expression.number(m.group(3)),circle=radius.mul(pi).mul(Rational.of(2)),arc=circle.mul(angle).div(Rational.of(360)),answer=arc.add(radius.mul(Rational.of(2)));assertTrue(new Checker().check(q,List.of(),List.of(answer.toString())).correct());assertEquals("sector",q.diagram.type);variants.add(m.group(3));if(angle.compareTo(Rational.of(180))>0)variants.add("major");verify(q,List.of(radius,angle,pi,circle,arc,answer));}assertEquals(Set.of("3.14","22/7","major"),variants);}
 @Test public void savedFractionalRadiusAndAngleRemainExact(){verify(new Question("sectorPerimeter","반지름: 1/2cm · 중심각: 45/2°\nπ = 22/7 사용\n부채꼴의 전체 둘레는 몇 cm인가요?","","67/56"),List.of(Rational.of(1,2),Rational.of(45,2),Rational.of(22,7),Rational.of(22,7),Rational.of(11,56),Rational.of(67,56)));}
 @Test public void oldCircumferenceDraftCannotBecomeRadius(){Question q=new Question("sectorPerimeter","반지름: 21cm · 중심각: 90°\nπ = 22/7 사용\n부채꼴의 전체 둘레는 몇 cm인가요?","","75");HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("132",""));p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));d.entries.set(0,"21");d.stage=1;HelpPlan.Draft restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("21",restored.entries.get(0));}
 private void verify(Question q,List<Rational> expected){String signature=q.signature();Arrays.fill(q.answers,"999999");q.choiceInputs=new Rational[]{Rational.of(999999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertEquals(6,p.size());assertFalse(p.canTransfer());for(int k=0;k<6;k++){assertTrue(p.step(k).accepts(expected.get(k).toString()));assertFalse(p.step(k).accepts(expected.get(k).add(Rational.ONE).toString()));assertFalse(p.step(k).before.replace("360","").replace("2","").matches("(?s).*\\d.*"));}}
}
